import json,os,pathlib,subprocess,sys
repo=pathlib.Path('/home/bamedeo/kin-wt/build-time');base=pathlib.Path('/mnt/windows/Users/amedeo/Desktop/gamedev');out=base/'kin-header-deps-bench';phase=sys.argv[1];header=repo/'engine/include/kin/platform/app.hpp';env={**os.environ,'TMPDIR':str(base/'kin-header-deps-tmp')};rows=[]
expected={r['compiler']:r['cpp_objects'] for r in json.loads((out/(phase+'-fanout.json')).read_text()) if r['header'].endswith('/app.hpp') and r['target']=='hex_demo'}
for run in range(3):
 order=['clang','gcc'] if (run+(phase=='after'))%2==0 else ['gcc','clang']
 for compiler in order:
  build=base/('kin-build-time-clang' if compiler=='clang' else 'kin-build-time-out');original=header.read_bytes();stat=header.stat();label=f'{phase}-{compiler}-{run}'
  try:
   header.write_bytes(original+f'\n// Header edit benchmark {run}.\n'.encode())
   with (out/(label+'.log')).open('w') as log:r=subprocess.run(['/usr/bin/time','-f','{"wall_seconds":%e,"user_seconds":%U,"system_seconds":%S,"max_child_rss_kib":%M}','-o',str(out/(label+'.stats.json')),'taskset','-c','0,2,4,6','cmake','--build',str(build),'--parallel','4','--target','hex_demo'],env=env,stdout=log,stderr=subprocess.STDOUT)
   if r.returncode:print((out/(label+'.log')).read_text()[-8000:],flush=True);raise SystemExit(r.returncode)
   actions=[l for l in (out/(label+'.log')).read_text().splitlines() if l.startswith('[') and 'Re-checking globbed directories' not in l];cpp=[l.split('Building CXX object ',1)[1] for l in actions if 'Building CXX object ' in l];assert len(cpp)==expected[compiler],actions
   row={'phase':phase,'compiler':compiler,'run':run,**json.loads((out/(label+'.stats.json')).read_text()),'cpp_objects_including_pch':len(cpp),'object_outputs':cpp,'actions':actions};rows.append(row);(out/(phase+'-timings.json')).write_text(json.dumps(rows,indent=2)+'\n');print(json.dumps({k:v for k,v in row.items() if k not in ['object_outputs','actions']}),flush=True)
  finally:header.write_bytes(original);os.utime(header,ns=(stat.st_atime_ns,stat.st_mtime_ns))

